<?php
declare(strict_types=1);
namespace WordPressNewsBot\Tests;
use PHPUnit\Framework\TestCase;
final class AdminCredentialSafetyTest extends TestCase { public function testAdminNeverRendersPostedApiKeyOrExposesRestRoute():void{$source=file_get_contents(dirname(__DIR__).'/admin/Admin.php');$this->assertStringContainsString('type="password"',$source);$this->assertStringContainsString('autocomplete="new-password"',$source);$this->assertStringNotContainsString("value=\"'.esc_attr(\$key)",$source);$this->assertStringNotContainsString('register_rest_route',$source);} public function testCredentialOptionIsNotExportedByAdmin():void{$source=file_get_contents(dirname(__DIR__).'/admin/Admin.php');$this->assertStringNotContainsString('wpnb_openai_credentials',$source);} public function testAllCredentialActionsRequirePostCapabilityAndNonce():void{$source=file_get_contents(dirname(__DIR__).'/admin/Admin.php');$this->assertStringContainsString("requirePostAction('wpnb_save_test_openai')",$source);$this->assertStringContainsString("requirePostAction('wpnb_retest_openai')",$source);$this->assertStringContainsString("requirePostAction('wpnb_delete_openai')",$source);$this->assertStringContainsString("REQUEST_METHOD",$source);$this->assertStringContainsString('Security::canManage()',$source);$this->assertStringContainsString('check_admin_referer',$source);} }
